// Loader paths may have a native prefix and either slash spelling. Require the
// full ui/movie suffix at a component boundary, then the complete movie hash.
inline bool native_art_movie_path(const char* path,const char* suffix) noexcept {
    if(!path || !suffix)return false;
    const auto length=strnlen(path,256),tail=std::strlen(suffix);
    if(!length || length==256 || length<tail)return false;
    const auto start=length-tail;
    if(start && path[start-1]!='/' && path[start-1]!='\\')return false;
    const auto normalized=[](unsigned char c) {
        if(c=='\\')return static_cast<unsigned char>('/');
        return c>='A' && c<='Z'?static_cast<unsigned char>(c+('a'-'A')):c;
    };
    for(std::size_t i=0;i<tail;++i)
        if(normalized(static_cast<unsigned char>(path[start+i]))!=normalized(static_cast<unsigned char>(suffix[i])))return false;
    return true;
}
inline NativeArtMovieResult patch_native_art_movie(const char* path,unsigned char* data,std::size_t size) noexcept {
    if(!path || !data)return NativeArtMovieResult::unsupported;
    std::array<const NativeArtMovieEdit*,4> chain{};std::size_t n=0; // this movie's rows, applied in table order
    for(const auto& movie:native_art_movie_edits)if(native_art_movie_path(path,movie.path) && n<chain.size())chain[n++]=&movie;
    if(!n)return NativeArtMovieResult::unsupported;
    for(std::size_t i=0;i<n;++i)if(size!=chain[i]->size || chain[i]->offset>size || chain[i]->count>size-chain[i]->offset)return NativeArtMovieResult::rejected;
    std::array<unsigned char,32> digest{};
    const auto hash=[&] {return BCryptHash(BCRYPT_SHA256_ALG_HANDLE,nullptr,0,data,static_cast<ULONG>(size),digest.data(),static_cast<ULONG>(digest.size()))>=0;};
    if(!hash())return NativeArtMovieResult::rejected;
    std::size_t start=0; // a cached buffer already carries some rows: resume after the last one whose result it is
    for(std::size_t i=0;i<n;++i)if(digest==chain[i]->patched_sha256 && !std::memcmp(data+chain[i]->offset,chain[i]->new_bytes.data(),chain[i]->count))start=i+1;
    if(start==n)return NativeArtMovieResult::already;
    for(std::size_t i=start;i<n;++i) {
        const auto& m=*chain[i];
        if(digest!=m.original_sha256 || std::memcmp(data+m.offset,m.old_bytes.data(),m.count))return i==start?NativeArtMovieResult::rejected:NativeArtMovieResult::patched;
        std::memcpy(data+m.offset,m.new_bytes.data(),m.count);
        if(i+1<n && !hash())return NativeArtMovieResult::patched;
    }
    return NativeArtMovieResult::patched;
}
inline std::atomic<std::uint64_t> native_art_movie_patched{},native_art_movie_rejected{};
inline bool patch_vr_native_art_movie(const char* path,unsigned char* data,std::size_t size) noexcept {
    const auto result=patch_native_art_movie(path,data,size);
    if(result==NativeArtMovieResult::patched)++native_art_movie_patched;
    if(result==NativeArtMovieResult::rejected)++native_art_movie_rejected;
    return result==NativeArtMovieResult::patched || result==NativeArtMovieResult::already;
}

// Runtime remap of the Dishonored 2 button-prompt glyphs to Quest VR control labels.
//
// ui/lib_controller_buttons.iggy is the prompt movie; its pixels live in the sibling
// ui/lib_controller_buttons.raw.iggytex (410128 B). That pack is NOT one shared atlas:
// it is a headerless concatenation of 159 BC7 textures (DXGI_FORMAT_BC7_UNORM, 16-byte
// 4x4 blocks, one mip, no padding), one per movie bitmap, in the order of the movie's own
// texture table (tag block at file offset 0x30500: u16 count=159, u16 unused,
// u32 totalBytes=410128, then 159 x {u8 0x0d, u8 0x01, u16 width, u16 height, u16 index,
// u32 byteOffset}). Every bitmap's UV rect is its whole texture (0,0..1,1), so each glyph
// is uploaded as its own D3D11 texture: there is nothing to blit inside an atlas.
//
// Hook point: ID3D11Device::CreateTexture2D with Format BC7_UNORM/BC7_UNORM_SRGB,
// MipLevels==1, ArraySize==1 and D3D11_SUBRESOURCE_DATA::pSysMem set. Compute
// atlas_signature(pSysMem, ceil(w/4)*ceil(h/4)*16) and look it up with
// find_xbox_glyph(desc.Width, desc.Height, signature): on a hit replace that texture with
// an uncompressed R8G8B8A8 texture painted by paint_quest_glyphs (the engine samples the
// SRV, so the format change is invisible to the movie), or re-encode the packed rects
// offline. Ark's own Iggy substitution path (IggyGenericSetTextureFromResource,
// arkIggyTextureSubstitutionManager) is an alternative hook if reachable.
//
// Glyph identity was established by decoding every BC7 texture and reading it; the 30
// _XBOX crops and the labelled contact sheet are in artifacts/research/glyphs/rects/ and
// artifacts/research/glyphs/rects_sheet.png.
struct GlyphRect {const char* name;unsigned x,y,w,h;};
struct GlyphTexture {const char* name;const char* label;unsigned offset,bytes,width,height;std::uint64_t signature;};

inline constexpr unsigned kGlyphPackBytes=410128;
inline constexpr unsigned kGlyphPackTextures=159;
inline constexpr unsigned kGlyphBlockBytes=16;
inline constexpr unsigned kGlyphFormat=98;      // DXGI_FORMAT_BC7_UNORM
inline constexpr unsigned kGlyphFormatSrgb=99;  // DXGI_FORMAT_BC7_UNORM_SRGB
inline constexpr std::uint64_t kGlyphPackSignature=0x9a1be1a4ec42e72full;

