// FNV-1a over the uploaded texture size plus a fixed sample of its bytes: every byte for
// textures up to 16 KiB (all controller glyphs), otherwise head 4 KiB, an even stride
// across the middle and the last 4 KiB. Used to recognise the pack's initial data.
inline std::uint64_t atlas_signature(const void* data,std::size_t size) {
    const auto* bytes=static_cast<const std::uint8_t*>(data);
    std::uint64_t hash=14695981039346656037ull;
    const auto mix=[&hash](std::uint8_t value) {hash^=value;hash*=1099511628211ull;};
    mix(static_cast<std::uint8_t>(size&0xff));mix(static_cast<std::uint8_t>((size>>8)&0xff));
    mix(static_cast<std::uint8_t>((size>>16)&0xff));mix(static_cast<std::uint8_t>((size>>24)&0xff));
    if(!bytes || !size) return hash;
    if(size<=16384) {for(std::size_t i=0;i<size;++i) mix(bytes[i]);}
    else {
        constexpr std::size_t head=4096,tail=4096;
        const std::size_t step=std::max<std::size_t>(1,(size-head-tail)/8192);
        for(std::size_t i=0;i<head;++i) mix(bytes[i]);
        for(std::size_t i=head;i+tail<size;i+=step) mix(bytes[i]);
        for(std::size_t i=size-tail;i<size;++i) mix(bytes[i]);
    }
    return hash;
}

inline const GlyphTexture* find_xbox_glyph(unsigned width,unsigned height,std::uint64_t signature) {
    for(const auto& glyph:kXboxGlyphs) if(glyph.width==width && glyph.height==height && glyph.signature==signature) return &glyph;
    return nullptr;
}

inline const GlyphTexture* find_xbox_glyph(unsigned width,unsigned height,const void* data,std::size_t size) {
    return find_xbox_glyph(width,height,atlas_signature(data,size));
}

// White label on a dark rounded card drawn with GDI; only pixels inside rect are touched,
// and pixels the GDI card leaves black become fully transparent.
inline void paint_quest_glyphs(std::uint8_t* rgba,unsigned width,unsigned height,const GlyphRect& rect,const char* label) {
    if(!rgba || !label || !*label || !rect.w || !rect.h || rect.x+rect.w>width || rect.y+rect.h>height) return;
    struct Bitmap {
        HDC dc{};HBITMAP bitmap{};HGDIOBJ previous{};void* bits{};
        Bitmap(int w,int h) {
            dc=CreateCompatibleDC(nullptr);BITMAPINFO info{};info.bmiHeader.biSize=sizeof(BITMAPINFOHEADER);
            info.bmiHeader.biWidth=w;info.bmiHeader.biHeight=-h;info.bmiHeader.biPlanes=1;
            info.bmiHeader.biBitCount=32;info.bmiHeader.biCompression=BI_RGB;
            bitmap=CreateDIBSection(dc,&info,DIB_RGB_COLORS,&bits,nullptr,0);
            if(dc && bitmap) previous=SelectObject(dc,bitmap);
        }
        ~Bitmap() {if(previous) SelectObject(dc,previous);if(bitmap) DeleteObject(bitmap);if(dc) DeleteDC(dc);}
    } image(static_cast<int>(rect.w),static_cast<int>(rect.h));
    if(!image.dc || !image.bitmap) throw std::runtime_error("Cannot allocate controller glyph bitmap");
    const int w=static_cast<int>(rect.w),h=static_cast<int>(rect.h);
    RECT all{0,0,w,h};auto background=CreateSolidBrush(RGB(0,0,0));FillRect(image.dc,&all,background);DeleteObject(background);
    const int margin=std::max(1,w/12);
    auto pen=CreatePen(PS_SOLID,1,RGB(93,211,233));auto old_pen=SelectObject(image.dc,pen);
    auto brush=CreateSolidBrush(RGB(17,24,32));auto old_brush=SelectObject(image.dc,brush);
    RoundRect(image.dc,margin,margin,w-margin,h-margin,std::max(3,w/4),std::max(3,h/4));
    SelectObject(image.dc,old_brush);SelectObject(image.dc,old_pen);DeleteObject(brush);DeleteObject(pen);
    // "+" becomes " + " so compound labels keep a wrap point, then the font shrinks until
    // the wrapped text fits the card.
    std::wstring text;
    for(const char* letter=label;*letter;++letter) {if(*letter=='+') text+=L" + ";else text+=static_cast<wchar_t>(*letter);}
    const auto make_font=[&](int size) {return CreateFontW(-size,0,0,0,FW_SEMIBOLD,FALSE,FALSE,FALSE,DEFAULT_CHARSET,
        OUT_DEFAULT_PRECIS,CLIP_DEFAULT_PRECIS,ANTIALIASED_QUALITY,DEFAULT_PITCH,L"Segoe UI");};
    RECT inner{margin,margin,w-margin,h-margin};
    int point=std::max(7,static_cast<int>(std::lround(h*(text.size()<=3?0.42:0.30)))),used=0;
    auto font=make_font(point);auto old_font=SelectObject(image.dc,font);
    SetTextColor(image.dc,RGB(236,241,245));SetBkMode(image.dc,TRANSPARENT);
    for(;;) {
        RECT measure{inner.left,inner.top,inner.right,inner.top};
        DrawTextW(image.dc,text.c_str(),-1,&measure,DT_CENTER|DT_WORDBREAK|DT_CALCRECT);
        used=measure.bottom-measure.top;
        // A single long word does not wrap, so the width has to fit as well.
        if((used<=h-2*margin && measure.right-measure.left<=inner.right-inner.left) || point<=6) break;
        SelectObject(image.dc,old_font);DeleteObject(font);
        font=make_font(--point);old_font=SelectObject(image.dc,font);
    }
    const int top=inner.top+std::max(0,(h-used)/2);
    RECT draw{inner.left,top,inner.right,top+used};
    DrawTextW(image.dc,text.c_str(),-1,&draw,DT_CENTER|DT_WORDBREAK);
    SelectObject(image.dc,old_font);DeleteObject(font);
    GdiFlush();
    const auto* raw=static_cast<const unsigned char*>(image.bits);
    for(unsigned y=0;y<rect.h;++y) for(unsigned x=0;x<rect.w;++x) {
        const auto* source=raw+(static_cast<std::size_t>(y)*rect.w+x)*4;
        auto* target=rgba+(static_cast<std::size_t>(rect.y+y)*width+rect.x+x)*4;
        // Transparent pixels carry the card colour so BC7 blocks on the card edge only vary in alpha.
        const bool opaque=(source[0]|source[1]|source[2])!=0;
        target[0]=opaque?source[2]:17;target[1]=opaque?source[1]:24;target[2]=opaque?source[0]:32;
        target[3]=opaque?255:0;
    }
}

// Whole-image variant: the caller passes a single decoded glyph texture.
inline void paint_quest_glyphs(std::uint8_t* rgba,unsigned width,unsigned height,const char* label) {
    paint_quest_glyphs(rgba,width,height,GlyphRect{label,0,0,width,height},label);
}
